日志系统需要按需创建不同的日志记录器（写文件、写控制台），用工厂方法让子类决定创建哪种记录器。下面是用 C++ 实现的工厂方法模式，类图如下，代码中只有一处空缺。代码省略了 #include 和 using namespace std;。

![类图](uml/pattern-factory-method.svg)

```cpp
class Logger {
public:
    ______ void log(const string& msg) = 0;
    virtual ~Logger() { }
};

class FileLogger : public Logger {
public:
    void log(const string& msg) {
        cout << "[file] " << msg << endl;
    }
};

class ConsoleLogger : public Logger {
public:
    void log(const string& msg) {
        cout << "[console] " << msg << endl;
    }
};

class LoggerFactory {
public:
    virtual Logger* createLogger() = 0;
    void write(const string& msg) {
        Logger* logger = createLogger();
        logger->log(msg);
        delete logger;
    }
    virtual ~LoggerFactory() { }
};

class FileLoggerFactory : public LoggerFactory {
public:
    Logger* createLogger() {
        return new FileLogger();
    }
};

class ConsoleLoggerFactory : public LoggerFactory {
public:
    Logger* createLogger() {
        return new ConsoleLogger();
    }
};
```

