![类图](uml/pattern-abstract-factory.svg)

```cpp
class Button {
public:
    virtual void paint() = 0;
    virtual ~Button() { }
};
class TextBox {
public:
    virtual void paint() = 0;
    virtual ~TextBox() { }
};

class WinButton : public Button {
public:
    void paint() { cout << "win button" << endl; }
};
class WinTextBox : public TextBox {
public:
    void paint() {
        cout << "win textbox" << endl;
    }
};
class MacButton : public Button {
public:
    void paint() { cout << "mac button" << endl; }
};
class MacTextBox : public TextBox {
public:
    void paint() {
        cout << "mac textbox" << endl;
    }
};

class GUIFactory {
public:
    virtual Button* createButton() = ______;
    virtual TextBox* createTextBox() = 0;
    virtual ~GUIFactory() { }
};

class WinFactory : public GUIFactory {
public:
    Button* createButton() {
        return new WinButton();
    }
    TextBox* createTextBox() {
        return new WinTextBox();
    }
};

class MacFactory : public GUIFactory {
public:
    Button* createButton() {
        return new MacButton();
    }
    TextBox* createTextBox() {
        return new MacTextBox();
    }
};

class Client {
    Button* button;
    TextBox* textBox;
public:
    Client(GUIFactory* factory) {
        button = factory->createButton();
        textBox = factory->createTextBox();
    }
    void show() {
        button->paint();
        textBox->paint();
    }
    ~Client() { delete button; delete textBox; }
};
```

