class Image {
public:
    virtual void display() = 0;
    virtual ~Image() { }
};

class RealImage : public Image {
    string file;
public:
    RealImage(string f) : file(f) {
        cout << "loading " << f << endl;
    }
    void display() {
        cout << "display " << file << endl;
    }
};

class ProxyImage : public Image {
    string file;
    ______* real;
public:
    ProxyImage(string f) : file(f), real(nullptr) { }
    void display() {
        if (real == nullptr) {
            real = new RealImage(file);
        }
        real->display();
    }
    ~ProxyImage() { delete real; }
};
```

