public:
    void prepare() {
        boilWater();
        ______;
        pourInCup();
        addCondiments();
    }
    virtual ~Beverage() { }
protected:
    void boilWater() {
        cout << "boil water" << endl;
    }
    void pourInCup() {
        cout << "pour in cup" << endl;
    }
    virtual void brew() = 0;
    virtual void addCondiments() = 0;
};

class Tea : public Beverage {
protected:
    void brew() { cout << "steep tea" << endl; }
    void addCondiments() {
        cout << "add lemon" << endl;
