class Iterator {
public:
    virtual bool hasNext() = 0;
    virtual string next() = 0;
    virtual ~Iterator() { }
};

class Container {
public:
    virtual Iterator* getIterator() = 0;
    virtual ~Container() { }
};

class NameRepository : public Container {
    vector<string> names;
public:
    NameRepository() {
        names.push_back("Tom");
        names.push_back("Amy");
        names.push_back("Bob");
    }

