        NameIterator(NameRepository* r) : repo(r), index(0) { }
        bool hasNext() {
            return index < repo->names.size();
        }
        string next() {
            return repo->names[index++];
        }
    };

    Iterator* getIterator() {
        return new NameIterator(this);
    }
};
```

