class User;

class Mediator {
public:
    virtual void send(const string& msg, User* from) = 0;
    virtual ~Mediator() { }
};

class User {
    string name;
    Mediator* mediator;
public:
    User(string n, Mediator* m) : name(n), mediator(m) { }
    void send(const string& msg) {
        mediator->______(msg, this);
    }
    void receive(const string& msg) {
        cout << name << " got " << msg << endl;
    }
};

class ChatRoom : public Mediator {
    vector<User*> users;
public:
    void registerUser(User* u) {
        users.push_back(u);
    }
    void send(const string& msg, User* from) {
        for (size_t i = 0; i < users.size(); i++) {
            if (users[i] != from) users[i]->receive(msg);
        }
    }
};
